   544	export function isProviderExecutionSurfaceCandidate(relativePath: string, source: string): boolean {
   545	  if (!relativePath.endsWith('.ts')) return false;
   546	  if (/(?:^|\/)(?:tasks|tests|generated)(?:\/|$)/.test(relativePath)) return false;
   547	  if (relativePath === 'core/provider-process-registry.ts') return false;
   548	  if (/^providers\/(?:codex-cli|claude-cli|gemini-cli)\.ts$/.test(relativePath)) return true;
   549	  if (/providers\/(?:codex-cli|claude-cli|gemini-cli)\.js/.test(source)) return true;
   550	  if (/\brunHostRun\s*\(/.test(source)) return true;
   551	  // B-137a: strip documentation filename references before the provider-word
   552	  // scan. The words are matched case-insensitively, so a prose citation of
   553	  // "CLAUDE.md" (the project convention doc, referenced by many core modules)
   554	  // read as a provider reference: any file that both used child_process for git
   555	  // and cited that doc became an "unclassified provider execution surface".
   556	  // scope-contract.ts tripped exactly this way on a comment citing the handler
   557	  // convention -- a docs citation, not a provider workload. Several already
   558	  // inventoried files (audit-scan, audit-trigger, rollout-check,
   559	  // runtime-environment-checks) match for the same non-reason. Stripping only
   560	  // "<provider>.md" filenames keeps every real provider reference intact,
   561	  // including CLAUDE_CLI, claudeCli, 'claude' and providers/claude-cli.js.
   562	  const withoutDocReferences = source.replace(/\b(?:codex|claude|agy|gemini|antigravity)\.md\b/gi, '');
